/** @type {import('next').NextConfig} */
// The landing page and the search pages (states, slang, camp guide, privacy) are static HTML in public/,
// served at clean URLs through these rewrites. They are generated by scripts/build-seo.py.
//
// Security headers: every page gets a Content-Security-Policy. Static pages allow only their own inline scripts,
// by SHA-256 hash computed here at build time from the files in public/ (`npm run build` syncs the game first).
import fs from "node:fs";
import crypto from "node:crypto";

const sbHost = (() => { try { return new URL(String(process.env.NEXT_PUBLIC_SUPABASE_URL || process.env.SUPABASE_URL || "").trim().replace(/^["']|["']$/g, "")).host; } catch { return ""; } })();
const SB = sbHost ? `https://${sbHost} wss://${sbHost}` : "https://*.supabase.co wss://*.supabase.co";

function inlineHashes(file) {
  let html = "";
  try { html = fs.readFileSync(file, "utf8"); } catch { console.warn(`[csp] ${file} not found; its inline scripts will be blocked`); return ""; }
  const out = [];
  for (const m of html.matchAll(/<script(?![^>]*\bsrc=)([^>]*)>([\s\S]*?)<\/script>/gi)) {
    if (/type=["']application\/ld\+json["']/i.test(m[1])) continue; // data, never executed
    out.push(`'sha256-${crypto.createHash("sha256").update(m[2], "utf8").digest("base64")}'`);
  }
  return out.join(" ");
}
const H = { game: inlineHashes("public/game3d/index.html"), landing: inlineHashes("public/landing/index.html"), admin: inlineHashes("public/admin/index.html") };

const BASE = "default-src 'self'; base-uri 'none'; object-src 'none'; form-action 'self'; manifest-src 'self'; worker-src 'self'; upgrade-insecure-requests";
const FONTS = "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com";
const CSP = {
  game: `${BASE}; script-src 'self' ${H.game}; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; media-src 'self' data: blob:; font-src 'self' data:; connect-src 'self' data: blob: ${SB}; frame-ancestors 'self'`,
  landing: `${BASE}; script-src 'self' ${H.landing}; ${FONTS}; img-src 'self' data:; connect-src 'self' ${SB}; frame-ancestors 'self'`,
  content: `${BASE}; script-src 'self'; ${FONTS}; img-src 'self' data:; connect-src 'self'; frame-ancestors 'self'`,
  admin: `${BASE}; script-src 'self' ${H.admin}; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self' ${SB}; frame-ancestors 'none'`,
  // Next.js pages (/play only hosts the game frame): Next's own inline bootstrap scripts need 'unsafe-inline'
  next: `${BASE}; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-src 'self'; frame-ancestors 'self'`,
};
const csp = v => [{ key: "Content-Security-Policy", value: v }];

const nextConfig = {
  poweredByHeader: false,
  async rewrites() {
    return {
      beforeFiles: [
        { source: "/", destination: "/landing/index.html" },
        { source: "/admin", destination: "/admin/index.html" },
        { source: "/states", destination: "/seo/states/index.html" },
        { source: "/states/:slug([a-z-]+)", destination: "/seo/states/:slug.html" },
        { source: "/nysc-slang", destination: "/seo/nysc-slang.html" },
        { source: "/nysc-camp-guide", destination: "/seo/nysc-camp-guide.html" },
        { source: "/privacy", destination: "/seo/privacy.html" },
      ],
    };
  },
  async redirects() {
    return [
      // old/alternative addresses people may type or link to
      { source: "/slang", destination: "/nysc-slang", permanent: true },
      { source: "/guide", destination: "/nysc-camp-guide", permanent: true },
      { source: "/packing-list", destination: "/nysc-camp-guide#packing-list", permanent: true },
      { source: "/landing/index.html", destination: "/", permanent: true },
      // the old single-file game is retired
      { source: "/classic", destination: "/play", permanent: true },
      { source: "/game", destination: "/play", permanent: true },
      { source: "/game/index.html", destination: "/play", permanent: true },
    ];
  },
  async headers() {
    const noindex = [{ key: "X-Robots-Tag", value: "noindex" }];
    return [
      // everywhere
      { source: "/:path*", headers: [
        { key: "X-Content-Type-Options", value: "nosniff" },
        { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
        { key: "X-Frame-Options", value: "SAMEORIGIN" },
        { key: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=(), payment=(), usb=(), serial=(), browsing-topics=()" },
        { key: "Content-Security-Policy", value: CSP.next },
      ] },
      // per page type (later rules win over the defaults above)
      { source: "/", headers: csp(CSP.landing) },
      { source: "/game3d/:path*", headers: [...csp(CSP.game), ...noindex] },
      { source: "/states", headers: csp(CSP.content) },
      { source: "/states/:slug*", headers: csp(CSP.content) },
      { source: "/nysc-slang", headers: csp(CSP.content) },
      { source: "/nysc-camp-guide", headers: csp(CSP.content) },
      { source: "/privacy", headers: csp(CSP.content) },
      { source: "/admin", headers: [...csp(CSP.admin), ...noindex, { key: "X-Frame-Options", value: "DENY" }, { key: "Cache-Control", value: "no-store" }] },
      { source: "/admin/:path*", headers: [...csp(CSP.admin), ...noindex, { key: "X-Frame-Options", value: "DENY" }, { key: "Cache-Control", value: "no-store" }] },
      { source: "/seo/:dir/:file(.*\\.html)", headers: [...csp(CSP.content), ...noindex] },
      { source: "/seo/:file(.*\\.html)", headers: [...csp(CSP.content), ...noindex] },
      { source: "/seo/img/:path*", headers: [{ key: "Cache-Control", value: "public, max-age=604800" }] },
      { source: "/landing/img/:path*", headers: [{ key: "Cache-Control", value: "public, max-age=604800" }] },
      { source: "/game/config.js", headers: [{ key: "Cache-Control", value: "no-store" }] },
    ];
  },
};
export default nextConfig;
